324:   function collide() {
325:     const pRadius=playerModel?.userData.radius ?? 1.2;
326:     if(player.x < -12.9+pRadius*.3 || player.x > 12.9-pRadius*.3 || player.z < -8.0+pRadius*.3 || player.z > 8.0-pRadius*.3)return true;
327:     for(const item of obstacles) if(Math.hypot(player.x-item.x,player.z-item.z)<pRadius+item.r-.48)return true;
328:     for(const item of staticColliders) if(Math.hypot(player.x-item.x,player.z-item.z)<pRadius+item.r-.25)return true;
