336:     const aligned=Math.abs(angleDiff(player.angle,Math.PI/2))<target.angleTolerance;
337:     if(centered&&aligned&&Math.abs(player.v)<target.speedLimit) {parkingProgress+=dt;ui.status.textContent='HOLD STEADY';if(parkingProgress>.85)finishLevel();}
338:     else parkingProgress=Math.max(0,parkingProgress-dt*1.6);
