351:     else {ui.completeKicker.textContent=finalLevel?'PARKING CHAMPION':'NICE PARKING';ui.completeTitle.textContent=finalLevel?'All 50 levels cleared.':'Right on the mark.';}
352:     ui.completeText.textContent=`${finalLevel?'You mastered every bay.':levelHint(levelIndex)}  •  ${score}% parking score`;
353:     ui.next.innerHTML=finalLevel?'DRIVE AGAIN <span>↻</span>':'NEXT LEVEL <span>→</span>';
